#include <bits/stdc++.h>
using namespace std;
int main(){map<string,string> sym;string line;regex decl(R"(^\s*(int|float|char)\s+([A-Za-z_]\w*)\s*;\s*$)");regex assign(R"(^\s*([A-Za-z_]\w*)\s*=\s*(.+)\s*;\s*$)");
    cout<<"Enter declarations/assignments; finish with EOF (Ctrl+D):\n";while(getline(cin,line)){smatch m;if(regex_match(line,m,decl)){string t=m[1],v=m[2];if(sym.count(v))cout<<"Semantic error: redeclaration of "<<v<<'\n';else{sym[v]=t;cout<<"Declared "<<v<<" as "<<t<<'\n';}continue;}if(regex_match(line,m,assign)){string lhs=m[1],rhs=m[2];if(!sym.count(lhs)){cout<<"Semantic error: undeclared variable "<<lhs<<'\n';continue;}bool bad=false,hasFloat=false,hasChar=false;regex id(R"([A-Za-z_]\w*)"),num(R"(\b\d+(?:\.\d+)?\b)");for(sregex_iterator it(rhs.begin(),rhs.end(),id),e;it!=e;++it){string v=it->str();if(v=="true"||v=="false")continue;if(!sym.count(v)){cout<<"Semantic error: undeclared variable "<<v<<'\n';bad=true;}else{hasFloat|=sym[v]=="float";hasChar|=sym[v]=="char";}}for(sregex_iterator it(rhs.begin(),rhs.end(),num),e;it!=e;++it)hasFloat|=it->str().find('.')!=string::npos;if(hasChar && (rhs.find_first_of("+-*/")!=string::npos || sym[lhs]!="char")){cout<<"Semantic error: incompatible char expression\n";bad=true;}if(sym[lhs]=="int"&&hasFloat){cout<<"Semantic error: possible float-to-int conversion for "<<lhs<<'\n';bad=true;}if(!bad)cout<<"Assignment to "<<lhs<<" is type-compatible\n";continue;}cout<<"Syntax error: "<<line<<'\n';}
    cout<<"\nSymbol table\n";for(auto &[v,t]:sym)cout<<v<<" : "<<t<<'\n';
}
